#!/usr/bin/env python3
"""Publish parameterized source rows from the registry in the sources guide."""
from __future__ import annotations

import argparse
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from gpuwm.source_adapters import source_adapters

BEGIN = '<!-- model-sources:begin -->'
END = '<!-- model-sources:end -->'


def render():
    lines = [BEGIN, '## Model source IDs', '',
             'Generated by `python tools/source_registry_doc.py` from the source registry.', '',
             'Rows share acquisition and preparation routes. Runtime availability and weight',
             'licence checks still apply; a listed ID does not imply a measured forecast.', '',
             '| Source | Model | Packaged profile |', '|---|---|---|']
    for row in source_adapters():
        if row.model_key is not None:
            cells = (f'`{row.source_id}`', row.display_name,
                     f'`{row.packaged_profile}`' if row.packaged_profile else 'Not declared')
            lines.append('| ' + ' | '.join(str(c).replace('|', '&#124;') for c in cells) + ' |')
    return '\n'.join([*lines, END]) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    path = ROOT / 'docs/public/SOURCES.md'
    before = path.read_text()
    if BEGIN in before:
        start = before.index(BEGIN)
        stop = before.index(END, start) + len(END)
        after = before[:start] + render().rstrip('\n') + before[stop:]
    else:
        after = before.rstrip() + '\n\n' + render()
    if args.check:
        if before != after:
            parser.exit(1, 'Source registry documentation is stale.\n')
    elif before != after:
        path.write_text(after)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
